using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DifficultyLevels", menuName = "Data/DifficultyLevels/DifficultyLevels")]
public class DifficultyLevels : ScriptableObject
{
	[Header("Difficulty Level Datas")]
	[SerializeField]
	private DifficultyLevel anomalyLevel;

	[SerializeField]
	private DifficultyLevel astreaLevel;

	[Header("Assets")]
	[SerializeField]
	private MapHandler mapHandler;

	public float GetCurrentDifficultyLevelIncreaseMaxCorruptionPercentage()
	{
		return GetCurrentAreaDifficultyLevel().GetDifficultyLevelIncreaseMaxCorruptionPercentage();
	}

	public List<StartingEffect> GetCurrentDifficultyLevelStartingEffects(CorruptedAnimalData corruptedAnimalData, bool startOfBattle)
	{
		return GetCurrentAreaDifficultyLevel().GetDifficultyLevelStartingEffects(corruptedAnimalData, startOfBattle);
	}

	public int GetCurrentDifficultyLevelModifyEnemiesHighestIndex()
	{
		return GetCurrentAreaDifficultyLevel().GetDifficultyLevelModifyEnemiesHighestIndex();
	}

	public List<OmenLogicActionFace> GetCurrentDifficultyLevelOnShuffleDicePoolAction()
	{
		return GetCurrentAreaDifficultyLevel().GetDifficultyLevelOnShuffleDicePoolAction();
	}

	private DifficultyLevel GetCurrentAreaDifficultyLevel()
	{
		if (!mapHandler.IsOnAstreasHeart)
		{
			return anomalyLevel;
		}
		return astreaLevel;
	}

	public int GetDifficultyLevelsAmountWithoutHidden(bool getAnomalyLevel)
	{
		if (!getAnomalyLevel)
		{
			return astreaLevel.MaxNonHiddenLevel;
		}
		return anomalyLevel.MaxNonHiddenLevel;
	}

	public bool IsCurrentDifficultyLevelIncreasesCostsActive()
	{
		return GetCurrentAreaDifficultyLevel().IsIncreaseCostsDifficultyLevelActive();
	}

	public bool IsCurrentDifficultyLevelLessAccessibleDestroy()
	{
		return GetCurrentAreaDifficultyLevel().IsLessAccessibleDestroyDifficultyLevelActive();
	}
}
